/**
 * HAC-343 — preflight gates. These run before any result exists.
 *
 * Two things must be proven before an arm's output means anything:
 *
 * 1. **The oracle can fail.** Each family's `verify.mjs` is generated by the
 *    same generator that built its fixture. That makes it independent of the arm
 *    harness but not epistemically independent of fixture construction, so it is
 *    mutation-tested against constructed valid and invalid states rather than
 *    trusted because it reported success.
 *
 * 2. **The lock baselines actually lock.** An allow-all implementation would
 *    produce the same unsafe result on a cross-target coupling as a real
 *    per-target lock, and the finding would be worthless — a skeptical judge
 *    would correctly dismiss it as a strawman that never locked anything. A2
 *    must serialize everything; A3 must serialize same-target intents and
 *    parallelise distinct-target ones.
 *
 * Neither gate needs mined evidence, so both run in CI without the pinned
 * `workspacejson/cli` checkout.
 *
 * @see evidence/execution-semantics.json — oracleProtocol.discriminationGate
 * @see evidence/metric-definitions.json — arms.*.validityGate
 */
import { mkdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { beforeAll, describe, expect, it } from 'vitest';

import { buildFixture as buildBudget, FIXTURES as BUDGET_FIXTURES } from '../../hac-330/bin/build-fixtures.mjs';
import { buildFixture as buildRegistry, FIXTURES as REGISTRY_FIXTURES } from '../lib/families/registry.mjs';
import { SCENARIOS } from '../lib/corpus.mjs';
import { runArm } from '../lib/arms.mjs';
import { applyIntent, oracle, resetWorktree } from '../lib/executor.mjs';

const WORK = resolve(import.meta.dirname, '..', '.work', 'preflight');
const repos = {};

beforeAll(() => {
  mkdirSync(WORK, { recursive: true });
  buildBudget(join(WORK, 'budget'), BUDGET_FIXTURES.baseline);
  buildRegistry(join(WORK, 'registry'), REGISTRY_FIXTURES.baseline);
  repos.budget = join(WORK, 'budget');
  repos.registry = join(WORK, 'registry');
}, 120_000);

/** Apply a list of intents from the base snapshot, as a concurrent composition. */
function composeFromBase(repo, family, intents) {
  resetWorktree(repo);
  for (const intent of intents) applyIntent(repo, family, intent);
  return oracle(repo, family);
}

const scenario = (id) => SCENARIOS.find((s) => s.id === id);

/**
 * Tag intents with the same stable ids the runner assigns.
 *
 * arms.mjs asserts rather than defaults them: an undefined id would collapse
 * both intents onto one record and replay the wrong write in phase 2.
 */
const identify = (s) => s.intents.map((intent, index) => ({ ...intent, id: `i${index}` }));

describe('the oracle can fail — verifier discrimination', () => {
  describe.each([
    {
      family: 'budget',
      coupled: 'budget/coupled/alpha-beta',
      // Invalid on one path alone: 200 + 40 + 20 is far past the 130 ceiling.
      sameTargetInvalid: [{ op: 'set-reservation', path: 'services/alpha/reservation.json', service: 'alpha', reserved: 200 }],
    },
    {
      family: 'registry',
      coupled: 'registry/coupled/retire-vs-route',
      // Invalid on one path alone: a route to a service that was never declared.
      sameTargetInvalid: [{ op: 'add-route', path: 'routing/routes.json', route: '/ghost', service: 'ghost' }],
    },
  ])('$family', ({ family, coupled, sameTargetInvalid }) => {
    it('reports the untouched fixture as valid', () => {
      resetWorktree(repos[family]);
      const verdict = oracle(repos[family], family);

      expect(verdict.spawnFailed).toBe(false);
      expect(verdict.exitCode).toBe(0);
      expect(verdict.holds).toBe(true);
      // The verdict must be the exit code, and the record must carry the
      // provenance the packet cites.
      expect(verdict.verifierSha256).toMatch(/^[0-9a-f]{64}$/);
      expect(verdict.stateSha256).toMatch(/^[0-9a-f]{64}$/);
    });

    it('reports the coupled composition as a violation', () => {
      const verdict = composeFromBase(repos[family], family, scenario(coupled).intents);

      expect(verdict.spawnFailed).toBe(false);
      expect(verdict.exitCode).not.toBe(0);
      expect(verdict.holds).toBe(false);
    });

    it('reports a single-path invalid state as a violation', () => {
      const verdict = composeFromBase(repos[family], family, sameTargetInvalid);

      expect(verdict.holds).toBe(false);
      expect(verdict.exitCode).not.toBe(0);
    });

    it('returns to valid once the worktree is reset, so violations are not sticky', () => {
      composeFromBase(repos[family], family, scenario(coupled).intents);
      resetWorktree(repos[family]);

      expect(oracle(repos[family], family).holds).toBe(true);
    });
  });
});

describe('the lock baselines actually lock', () => {
  const sameTarget = SCENARIOS.filter((s) => s.label === 'SAME_TARGET_CONTENTION');
  const crossTarget = SCENARIOS.filter((s) => s.label === 'COUPLED' || s.label === 'INDEPENDENT');

  it.each(sameTarget.map((s) => [s.id, s]))('A2 serializes %s', (_id, s) => {
    const run = runArm({ arm: 'A2_global_lock', repo: repos[s.family], family: s.family, scenario: s, intents: identify(s) });

    expect(run.concurrent).toBe(false);
    expect(run.lockGroups).toEqual(['GLOBAL']);
  });

  it.each(crossTarget.map((s) => [s.id, s]))('A2 serializes %s too — the lock is global, not per target', (_id, s) => {
    const run = runArm({ arm: 'A2_global_lock', repo: repos[s.family], family: s.family, scenario: s, intents: identify(s) });

    expect(run.concurrent).toBe(false);
    expect(run.lockGroups).toEqual(['GLOBAL']);
  });

  it.each(sameTarget.map((s) => [s.id, s]))('A3 serializes %s — same target, one lock key', (_id, s) => {
    const run = runArm({ arm: 'A3_per_target_lock', repo: repos[s.family], family: s.family, scenario: s, intents: identify(s) });

    expect(run.lockGroups).toHaveLength(1);
    expect(run.concurrent).toBe(false);
  });

  it.each(crossTarget.map((s) => [s.id, s]))('A3 parallelises %s — distinct targets, distinct lock keys', (_id, s) => {
    const run = runArm({ arm: 'A3_per_target_lock', repo: repos[s.family], family: s.family, scenario: s, intents: identify(s) });

    // The other half of the gate: an A3 that serialized everything would be a
    // global lock wearing a per-target label, and its blindness to cross-target
    // coupling would prove nothing about per-target locking.
    expect(run.lockGroups).toHaveLength(2);
    expect(run.concurrent).toBe(true);
  });

  it('A2 re-reads inside the critical section rather than replaying approvals', () => {
    // This must use a CROSS-target pair to discriminate. On a same-target pair
    // (alpha->60 then alpha->55) the second projection is 115 whether or not the
    // first write was observed, because the second intent overwrites the same
    // key — so that assertion would pass vacuously and prove nothing.
    //
    // Cross-target separates the two behaviours cleanly. alpha->60 lands, then
    // beta->60 re-reads and projects 60+60+20 = 140, which does not fit and is
    // rejected. Had it replayed against the base snapshot it would have
    // projected 40+60+20 = 120, fitted, applied, and overshot to 140 — which is
    // exactly the strawman a lock baseline must not be.
    const s = scenario('budget/coupled/alpha-beta');
    const run = runArm({ arm: 'A2_global_lock', repo: repos.budget, family: 'budget', scenario: s, intents: identify(s) });

    expect(run.outcomes).toHaveLength(2);
    expect(run.outcomes[0].applied).toBe(true);
    expect(run.outcomes[0].detail).toContain('projected total 120');

    expect(run.outcomes[1].applied).toBe(false);
    expect(run.outcomes[1].reason).toBe('LOCAL_PRECONDITION_FAILED');
    expect(run.outcomes[1].detail).toContain('projected total 140');

    // And the state the oracle sees must be the safe one.
    expect(oracle(repos.budget, 'budget').holds).toBe(true);
  });

  it('A3 re-reads too, on a same-target pair where its lock is the one contending', () => {
    // A3's critical section is the same code, but only same-target intents
    // contend for it. Both fit here, so both apply and the last write wins —
    // what is being asserted is that the second ran inside the section at all.
    const s = scenario('budget/same-target/alpha-alpha');
    const run = runArm({ arm: 'A3_per_target_lock', repo: repos.budget, family: 'budget', scenario: s, intents: identify(s) });

    expect(run.lockGroups).toHaveLength(1);
    expect(run.outcomes.every((o) => o.applied)).toBe(true);
    expect(oracle(repos.budget, 'budget').holds).toBe(true);
  });
});
